import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import InputField from '../../../components/ui/InputField/InputField';
import api from '../../../api/api'; // Importa o nosso cliente da API

const ListOngsPage = () => {
  const [ongs, setOngs] = useState([]); // Estado para guardar as ONGs da API
  const [searchTerm, setSearchTerm] = useState('');

  const headers = ['ID', 'Nome Fantasia', 'CNPJ', 'Responsável', 'Email', 'Telefone'];

  // useEffect para ir buscar os dados ao backend quando a página carrega
  useEffect(() => {
    const fetchOngs = async () => {
      try {
        const response = await api.get('/ongs'); // Faz um pedido GET para /api/ongs
        setOngs(response.data); // Guarda os dados no estado
      } catch (error) {
        console.error("Erro ao buscar ONGs:", error);
      }
    };

    fetchOngs();
  }, []);

  // Filtra as ONGs com base no termo de pesquisa
  const filteredOngs = ongs.filter(ong =>
    ong.fantasy_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ong.responsible_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ong.contact_email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ong.phone.includes(searchTerm)
  );

  return (
    <ContentWrapper title="Listar ONGs">
      <div style={{ marginBottom: '1.5rem', maxWidth: '400px' }}>
        <InputField
          label="Pesquisar por nome, responsável, email ou telefone"
          name="search"
          placeholder="Digite para pesquisar..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>
      <Table headers={headers} data={filteredOngs} />
    </ContentWrapper>
  );
};

export default ListOngsPage;
